"use client"

import * as React from "react";

import { ChatPromptInput } from "@/components/ui/chat-prompt-input";

export function ChatInputDemo() {
  const [value, setValue] = React.useState("")
  const [mode, setMode] = React.useState<"gen-ui" | "chat">("chat")
  const [lastSubmission, setLastSubmission] = React.useState<{
    text: string
    mode: "gen-ui" | "chat"
  } | null>(null)

  const handleSubmit = (text: string, mode: "gen-ui" | "chat") => {
    setLastSubmission({ text, mode })
    setValue("")
  }

  return (
    <div className="w-full max-w-2xl min-w-0 space-y-4">
      {/* Reserve more headroom only while the floating project menu is open. */}
      <div className="pt-12 pb-2 has-[[data-slot=chat-prompt-context]]:pt-80">
        <ChatPromptInput
          value={value}
          onValueChange={setValue}
          mode={mode}
          onModeChange={setMode}
          onSubmit={handleSubmit}
          placeholder="Ask about a project…"
        />
      </div>
      {lastSubmission && (
        <div
          role="status"
          className="space-y-1.5 rounded-xl border border-border/80 bg-card/60 p-4 text-xs break-words"
        >
          <p className="font-semibold text-foreground">Last submission</p>
          <p className="text-muted-foreground">
            <span className="font-medium text-foreground">Mode:</span>{" "}
            {lastSubmission.mode === "gen-ui" ? "Gen UI" : "Chat"}
          </p>
          <p className="leading-relaxed text-muted-foreground">
            <span className="font-medium text-foreground">Prompt:</span> &quot;
            {lastSubmission.text}&quot;
          </p>
        </div>
      )}
    </div>
  )
}

